Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
ARM: EXYNOS: Fix potentian kfree() of ro memory

The change fixes a bug introduced by 2be2a3ff42a5, memory allocated
by kstrdup_const() must be always deallocated with kfree_const(),
otherwise there is a risk of kfree'ing ro memory in power domain error
exit path.

Signed-off-by: Vladimir Zapolskiy <vz@mleia.com>
Cc: <stable@vger.kernel.org>
Fixes: 2be2a3ff42a5 ("ARM: EXYNOS: register power domain driver from core_initcall")
Signed-off-by: Krzysztof Kozlowski <k.kozlowski@samsung.com>

Here is the root cause:
The bug was caused by using `kfree()` to deallocate memory that was allocated with `kstrdup_const()`, which requires `kfree_const()` for proper deallocation. This mismatch can lead to attempts to free read-only memory, resulting in potential crashes or undefined behavior in the power domain error exit path.

Here is the patch:

 static __init int exynos4_pm_init_power_domain(void)
 {
 	struct device_node *np;

 	for_each_compatible_node(np, NULL, "samsung,exynos4210-pd") {
 		struct exynos_pm_domain *pd;
 		int on, i;

 		pd = kzalloc(sizeof(*pd), GFP_KERNEL);
 		if (!pd) {
 			pr_err("%s: failed to allocate memory for domain\n",
 					__func__);
 			of_node_put(np);
 			return -ENOMEM;
 		}
 		pd->pd.name = kstrdup_const(strrchr(np->full_name, '/') + 1,
 					    GFP_KERNEL);
 		if (!pd->pd.name) {
 			kfree(pd);
 			of_node_put(np);
 			return -ENOMEM;
 		}

 		pd->name = pd->pd.name;
 		pd->base = of_iomap(np, 0);
 		if (!pd->base) {
 			pr_warn("%s: failed to map memory\n", __func__);
-			kfree(pd->pd.name);
+			kfree_const(pd->pd.name);
 			kfree(pd);
 			of_node_put(np);
 			continue;
 		}

 		pd->pd.power_off = exynos_pd_power_off;
 		pd->pd.power_on = exynos_pd_power_on;

 		for (i = 0; i < MAX_CLK_PER_DOMAIN; i++) {
 			char clk_name[8];

 			snprintf(clk_name, sizeof(clk_name), "asb%d", i);
 			pd->asb_clk[i] = of_clk_get_by_name(np, clk_name);
 			if (IS_ERR(pd->asb_clk[i]))
 				break;
 		}

 		pd->oscclk = of_clk_get_by_name(np, "oscclk");
 		if (IS_ERR(pd->oscclk))
 			goto no_clk;

 		for (i = 0; i < MAX_CLK_PER_DOMAIN; i++) {
 			char clk_name[8];

 			snprintf(clk_name, sizeof(clk_name), "clk%d", i);
 			pd->clk[i] = of_clk_get_by_name(np, clk_name);
 			if (IS_ERR(pd->clk[i]))
 				break;
 			/*
 			 * Skip setting parent on first power up.
 			 * The parent at this time may not be useful at all.
 			 */
 			pd->pclk[i] = ERR_PTR(-EINVAL);
 		}

 		if (IS_ERR(pd->clk[0]))
 			clk_put(pd->oscclk);

 no_clk:
 		on = __raw_readl(pd->base + 0x4) & INT_LOCAL_PWR_EN;

 		pm_genpd_init(&pd->pd, NULL, !on);
 		of_genpd_add_provider_simple(np, &pd->pd);
 	}

 	/* Assign the child power domains to their parents */
 	for_each_compatible_node(np, NULL, "samsung,exynos4210-pd") {
 		struct generic_pm_domain *child_domain, *parent_domain;
 		struct of_phandle_args args;

 		args.np = np;
 		args.args_count = 0;
 		child_domain = of_genpd_get_from_provider(&args);
 		if (IS_ERR(child_domain))
 			goto next_pd;

 		if (of_parse_phandle_with_args(np, "power-domains",
 					 "#power-domain-cells", 0, &args) != 0)
 			goto next_pd;

 		parent_domain = of_genpd_get_from_provider(&args);
 		if (IS_ERR(parent_domain))
 			goto next_pd;

 		if (pm_genpd_add_subdomain(parent_domain, child_domain))
 			pr_warn("%s failed to add subdomain: %s\n",
 				parent_domain->name, child_domain->name);
 		else
 			pr_info("%s has as child subdomain: %s.\n",
 				parent_domain->name, child_domain->name);
 next_pd:
 		of_node_put(np);
 	}

 	return 0;
 }
 core_initcall(exynos4_pm_init_power_domain);


